SELECT COUNT(*) AS sc_table_count_expected_5 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('run_start_culture_session','run_start_culture_receipt','run_workflow_step_visit','run_workflow_step_visit_member','alarm_start_culture_collection');
SELECT COUNT(*) AS sc_column_count_expected_16 FROM information_schema.columns WHERE table_schema=DATABASE() AND ((table_name='res_culture' AND column_name IN ('initial_weight_source_kind','initial_weight_workflow_id','cell_type_id','cell_type_name','cell_type_value','cell_type_prefix','cell_type_workflow_id','cell_type_effective_at','start_completed_workflow_id')) OR (table_name='run_workflow_instance' AND column_name IN ('workflow_kind','page_session_id','batch_id','business_date','deadline_at','active_start_culture_id','completed_start_culture_id')));
SELECT COUNT(*) AS source_errors_expected_0 FROM res_culture WHERE initial_weight_g IS NOT NULL AND initial_weight_source_kind IS NULL;
SELECT COUNT(*) AS runtime_stream_columns_expected_3 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='run_culture_runtime' AND column_name IN ('runtime_stream_id','runtime_stream_sequence','runtime_last_event_key');
SELECT culture_id,initial_weight_g,initial_weight_candidate_id,initial_weight_source_kind FROM res_culture WHERE culture_id=861016201;
SELECT subflow_id,node_id,subflow_code,lab_type,sort_order FROM workflow_subflow WHERE subflow_id IN (40011,40012);
SELECT subflow_id,COUNT(*) AS steps_expected_4 FROM workflow_step WHERE subflow_id IN (40011,40012) AND del_flag='0' GROUP BY subflow_id;
SELECT c.culture_id,c.culture_code,c.lab_id,c.mode_code,c.planned_start_date,c.lifecycle_state,c.first_workflow_started_at,c.start_completed_at,c.initial_weight_g,c.cell_type_id,o.occupancy_state,c.device_kind,c.device_id FROM res_culture c LEFT JOIN res_culture_occupancy o ON o.culture_id=c.culture_id AND o.active_slot=1 WHERE c.project_id=861017001 ORDER BY c.culture_id;
SELECT COUNT(*) AS initial_fixture_count_expected_6 FROM res_culture WHERE project_id=861017001 AND facts_status='READY' AND lifecycle_state='NOT_STARTED' AND planned_start_date=DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+08:00')) AND first_workflow_started_at IS NULL AND start_completed_at IS NULL AND initial_weight_g IS NULL AND cell_type_id IS NULL;
SELECT d.reactor_id,d.reactor_name,m.capacity,m.capacity_unit,d.status,d.ip_address,d.port FROM lab_bench_reactor d JOIN dev_bench_reactor m ON m.model_id=d.model_id WHERE d.create_by='SC_TEST_20261017';
SELECT d.integrated_id,d.reactor_name,m.spec,d.status,d.opc_ip,d.opc_port,s.scale_id,s.status AS floor_scale_status,s.ip_address,s.port FROM lab_integrated_reactor d JOIN dev_integrated_reactor m ON m.model_id=d.model_id JOIN lab_floor_scale s ON s.scale_id=d.floor_scale_id WHERE d.create_by='SC_TEST_20261017';
SELECT w.workflow_id,c.culture_code,w.state,w.application_state,v.step_code,v.visit_no,v.started_at,v.ended_at,v.end_reason,v.end_time_basis FROM run_workflow_instance w JOIN res_culture c ON c.culture_id=w.culture_id LEFT JOIN run_workflow_step_visit v ON v.page_session_id=w.page_session_id WHERE c.project_id=861017001 ORDER BY w.workflow_id,v.started_at;
SELECT c.culture_code,c.initial_weight_g,c.cell_type_id,c.start_completed_at,a.workflow_id AS alarm_saved_workflow FROM res_culture c LEFT JOIN alarm_start_culture_collection a ON a.culture_id=c.culture_id WHERE c.project_id=861017001 ORDER BY c.culture_id;
